def minimumTimeToActivateString(s: str, order: list[int], k: int) -> int:
    n = len(s)
    if k == 0:
        return 0

    def isActive(t):
        star = [0] * n
        for i in range(min(t+1, n)):
            star[order[i]] = 1
        count = 0
        i = 0
        while i < n:
            if star[i] == 0:
                j = i
                while j < n and star[j] == 0:
                    j += 1
                length = j - i
                # substrings with no star in this block = length \* (length + 1) // 2
                count += length * (length + 1) // 2
                i = j
            else:
                i += 1
        total = n * (n + 1) // 2
        with_star = total - count
        return with_star >= k

    left, right = 0, n
    ans = -1
    while left <= right:
        mid = (left + right) // 2
        if isActive(mid):
            ans = mid + 1
            right = mid - 1
        else:
            left = mid + 1
    return ans if ans <= n else -1
